import 'package:flutter/material.dart';
import 'package:uuid/uuid.dart';
import '../../core/database/app_database.dart';
import '../inspections/inspections_page.dart';
class BuildingsPage extends StatefulWidget{final Map<String,dynamic> project;const BuildingsPage({super.key,required this.project});@override State<BuildingsPage> createState()=>_BuildingsPageState();}
class _BuildingsPageState extends State<BuildingsPage>{List<Map<String,dynamic>> rows=[];@override void initState(){super.initState();load();}Future<void> load()async{rows=await AppDatabase.instance.query('buildings',where:'projectId=?',args:[widget.project['id']]);if(mounted)setState((){});}Future<void> add()async{final n=TextEditingController(),a=TextEditingController();String type='سكني',sys='خرسانة مسلحة';final ok=await showDialog<bool>(context:context,builder:(c)=>StatefulBuilder(builder:(c,set)=>AlertDialog(title:const Text('إضافة مبنى'),content:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:n,decoration:const InputDecoration(labelText:'اسم المبنى')),DropdownButtonFormField(value:type,items:const[DropdownMenuItem(value:'سكني',child:Text('سكني')),DropdownMenuItem(value:'إداري',child:Text('إداري')),DropdownMenuItem(value:'تعليمي',child:Text('تعليمي'))],onChanged:(v)=>set(()=>type=v!)),DropdownButtonFormField(value:sys,items:const[DropdownMenuItem(value:'خرسانة مسلحة',child:Text('خرسانة مسلحة')),DropdownMenuItem(value:'صلب',child:Text('صلب')),DropdownMenuItem(value:'مختلط',child:Text('مختلط'))],onChanged:(v)=>set(()=>sys=v!)),TextField(controller:a,decoration:const InputDecoration(labelText:'العنوان'))]),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:const Text('إلغاء')),FilledButton(onPressed:()=>Navigator.pop(c,true),child:const Text('حفظ'))])));if(ok==true&&n.text.isNotEmpty){await AppDatabase.instance.insert('buildings',{'id':const Uuid().v4(),'projectId':widget.project['id'],'name':n.text,'type':type,'structuralSystem':sys,'address':a.text});load();}}
@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:Text(widget.project['name'])),floatingActionButton:FloatingActionButton(onPressed:add,child:const Icon(Icons.add)),body:ListView(padding:const EdgeInsets.all(16),children:[const Text('المباني',style:TextStyle(fontSize:22,fontWeight:FontWeight.bold)),...rows.map((b)=>Card(child:ListTile(title:Text(b['name']),subtitle:Text('${b['type']} • ${b['structuralSystem']}'),onTap:()=>Navigator.push(c,MaterialPageRoute(builder:(_)=>BuildingInspectionPage(building:b)))))]));}}
